CREATE DATABASE IF NOT EXISTS stock_smartrestaurantqr CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE stock_smartrestaurantqr;

CREATE TABLE IF NOT EXISTS Categories (Id INT AUTO_INCREMENT PRIMARY KEY, Name VARCHAR(150) NOT NULL, Description VARCHAR(500), IsDeleted BIT NOT NULL DEFAULT 0, DeletedAt DATETIME(6), CreatedAt DATETIME(6) NOT NULL, UpdatedAt DATETIME(6), UNIQUE KEY UX_Categories_Name(Name));
CREATE TABLE IF NOT EXISTS Suppliers (Id INT AUTO_INCREMENT PRIMARY KEY, Name VARCHAR(200) NOT NULL, ContactName VARCHAR(150), Phone VARCHAR(50), Email VARCHAR(200), Address VARCHAR(300), IsDeleted BIT NOT NULL DEFAULT 0, DeletedAt DATETIME(6), CreatedAt DATETIME(6) NOT NULL, UpdatedAt DATETIME(6), INDEX IX_Suppliers_Name(Name));
CREATE TABLE IF NOT EXISTS Products (Id INT AUTO_INCREMENT PRIMARY KEY, Code VARCHAR(50) NOT NULL, Name VARCHAR(150) NOT NULL, Description VARCHAR(1000), CategoryId INT NOT NULL, SupplierId INT NULL, Price DECIMAL(18,2) NOT NULL, Cost DECIMAL(18,2) NOT NULL, Stock DECIMAL(18,3) NOT NULL, MinStock DECIMAL(18,3) NOT NULL, ImagePath VARCHAR(500), Unit VARCHAR(30) NOT NULL, IsDeleted BIT NOT NULL DEFAULT 0, DeletedAt DATETIME(6), CreatedAt DATETIME(6) NOT NULL, UpdatedAt DATETIME(6), UNIQUE KEY UX_Products_Code(Code), INDEX IX_Products_Name_Category(Name,CategoryId), CONSTRAINT FK_Products_Categories FOREIGN KEY(CategoryId) REFERENCES Categories(Id), CONSTRAINT FK_Products_Suppliers FOREIGN KEY(SupplierId) REFERENCES Suppliers(Id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS Sales (Id INT AUTO_INCREMENT PRIMARY KEY, SaleNumber VARCHAR(80) NOT NULL, SaleDate DATETIME(6) NOT NULL, TotalAmount DECIMAL(18,2) NOT NULL, UserId VARCHAR(80) NOT NULL, CustomerName VARCHAR(200), Notes VARCHAR(1000), ExternalReference VARCHAR(100), IsDeleted BIT NOT NULL DEFAULT 0, DeletedAt DATETIME(6), CreatedAt DATETIME(6) NOT NULL, UpdatedAt DATETIME(6), UNIQUE KEY UX_Sales_Number(SaleNumber), UNIQUE KEY UX_Sales_External(ExternalReference), INDEX IX_Sales_Date(SaleDate));
CREATE TABLE IF NOT EXISTS SaleDetails (Id INT AUTO_INCREMENT PRIMARY KEY, SaleId INT NOT NULL, ProductId INT NOT NULL, Quantity DECIMAL(18,3) NOT NULL, UnitPrice DECIMAL(18,2) NOT NULL, SubTotal DECIMAL(18,2) NOT NULL, IsDeleted BIT NOT NULL DEFAULT 0, DeletedAt DATETIME(6), CreatedAt DATETIME(6) NOT NULL, UpdatedAt DATETIME(6), CONSTRAINT FK_Details_Sales FOREIGN KEY(SaleId) REFERENCES Sales(Id) ON DELETE CASCADE, CONSTRAINT FK_Details_Products FOREIGN KEY(ProductId) REFERENCES Products(Id));
CREATE TABLE IF NOT EXISTS StockMovements (Id INT AUTO_INCREMENT PRIMARY KEY, ProductId INT NOT NULL, MovementType INT NOT NULL, Quantity DECIMAL(18,3) NOT NULL, PreviousStock DECIMAL(18,3) NOT NULL, NewStock DECIMAL(18,3) NOT NULL, Reference VARCHAR(150), UserId VARCHAR(80) NOT NULL, Notes VARCHAR(1000), IsDeleted BIT NOT NULL DEFAULT 0, DeletedAt DATETIME(6), CreatedAt DATETIME(6) NOT NULL, UpdatedAt DATETIME(6), INDEX IX_Movements_Product_Date(ProductId,CreatedAt), CONSTRAINT FK_Movements_Products FOREIGN KEY(ProductId) REFERENCES Products(Id));
CREATE TABLE IF NOT EXISTS AuditLogs (Id INT AUTO_INCREMENT PRIMARY KEY, UserId VARCHAR(80) NOT NULL, Action VARCHAR(60) NOT NULL, EntityName VARCHAR(100) NOT NULL, EntityId VARCHAR(80), OldValues LONGTEXT, NewValues LONGTEXT, Timestamp DATETIME(6) NOT NULL, IsDeleted BIT NOT NULL DEFAULT 0, DeletedAt DATETIME(6), CreatedAt DATETIME(6) NOT NULL, UpdatedAt DATETIME(6));
CREATE TABLE IF NOT EXISTS SystemSettings (Id INT AUTO_INCREMENT PRIMARY KEY, `Key` VARCHAR(100) NOT NULL, `Value` VARCHAR(500) NOT NULL, Description VARCHAR(500), IsDeleted BIT NOT NULL DEFAULT 0, DeletedAt DATETIME(6), CreatedAt DATETIME(6) NOT NULL, UpdatedAt DATETIME(6), UNIQUE KEY UX_Settings_Key(`Key`));

-- Los datos de ejemplo se insertan de forma idempotente desde DataSeeder al iniciar la aplicación.
